package project.init.account.controller;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.GetMapping;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RestController;import project.init.account.domain.dto.AccountDto;import project.init.account.domain.entity.Account;import project.init.account.repository.AccountRepository;import java.util.ArrayList;import java.util.List;@Slf4j@RestController@RequestMapping("/account")@RequiredArgsConstructorpublic class AccountController {    private final AccountRepository accountRepository;    @GetMapping("/ping")    public String pingTest() {        List<Account> tList = accountRepository.findAll();        return "pong";    }    @GetMapping("/filter")    public ResponseEntity<List<AccountDto>> filter() {        return new ResponseEntity<>(new ArrayList<>(), HttpStatus.OK);    }}